from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class AlarmsSummarySlot(SchemaObject):
    critical = SchemaField(name="critical")
    major = SchemaField(name="major")
    minor = SchemaField(name="minor")
    warning = SchemaField(name="warning")
    indeterminate = SchemaField(name="indeterminate")

    def __init__(self, critical, major, minor, warning, indeterminate):
        self.critical = critical
        self.major = major
        self.minor = minor
        self.warning = warning
        self.indeterminate = indeterminate
        super(AlarmsSummarySlot, self).__init__()


class AlarmsSummaryV1(SchemaObject):
    severity = SchemaField(name="severity", klass=AlarmsSummarySlot)
    total = SchemaField(name="total", optional=True)
    def __init__(self, severity, total):
        self.severity = severity
        self.total = total
        super(AlarmsSummaryV1, self).__init__()
